window.BC=window.BC||{};window.BC.meta={"CAISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL": "Coal", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["LA_BASIN", "NP15", "SDGE", "SP15_rest", "ZP26"]}, "ERCOT": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_LIGNITE", "COAL_PRB", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["Houston", "North", "Northeast", "South", "South_Central", "West"]}, "MISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_LIGNITE", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["MISO-East", "MISO-Illinois", "MISO-Indiana", "MISO-Plains", "MISO-South", "MISO-West"]}, "NEISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2022, 2023, 2024, 2025], "zones": ["Boston", "Central", "Connecticut", "North"]}, "NYISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP"], "years": [2023, 2024, 2025], "zones": ["Capital_Hudson", "Long_Island", "Lower_Hudson", "NYC", "Upstate_West"]}, "PJM": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "COAL_WC": "Coal Waste", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_PRB", "COAL_BIT", "COAL_WC", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2022, 2023, 2024, 2025], "zones": ["PJM_AEP_Ohio", "PJM_ATSI", "PJM_Central_PA", "PJM_ComEd", "PJM_Dominion", "PJM_EMAAC", "PJM_SWMAAC", "PJM_West_APS"]}};window.BC.manifest=[{"date": "2026-07-30", "definition": "pjm-140: ramp_limits False->True on the measured PJM CAMPD ramp envelope", "file": "frontend/data/backcast/runs/2026-07-30-pjm-140-rampenv.js", "id": "2026-07-30-pjm-140-rampenv", "iso": "PJM", "label": "pjm 140 rampenv", "shorthand": "pjm-140-rampenv", "years": [2023, 2024, 2025]}, {"date": "2026-07-31", "definition": "neiso-72 KEEPER (promoted 2026-07-31, was 2026-07-31-neiso-71-nucavail): the neiso-71 keeper recipe with ONE structural delta -- constants.EIA930_PS_SPLIT_COMPLETE_FROM = {'NEISO': 2025}, which makes data.hydro.eia930_wat_level_folded refuse the EIA-930 NG:WAT monthly hydro LEVEL pin per-year for any backcast year before NEISO's first wholly-split calendar year (first filed NG:PS hour 2024-11-07) -- design D, a whole-year basis rule, never a mid-year splice. The pre-split NG:WAT series folds in ~1.9 TWh/yr of pumped-storage gross discharge (measured four independent ways); 2023/2024 hydro levels move to the units' own EIA-923 HY filings (builder budgets 8.5762/6.7144 TWh vs the 8.7750/7.3942 TWh NG:WAT-pinned basis), while 2025 -- the first wholly-split year -- keeps the pin and is BIT-IDENTICAL to the control (class_hourly/system/storage sidecars .equals=True). Zero fitted scalars (the refusal REMOVES a mechanism rather than adding one); scored against same-HEAD control 2026-07-31-neiso-72-control (neiso72_control_A, HEAD 10c624e), which reproduces the neiso-71 keeper to 4 decimals. Determination CALIBRATED-WITH-CAVEATS, every criterion identical to the outgoing neiso-71 keeper: 6 PASS (C1/C2/C3a/C3b/C4/C6), C3c price-tail CAVEAT ledgered (model 0h vs RT actual 15h/2023 and 20h/2025, >$300 -- accepted measured-input limitation, 2026-07-11 frontier), C7 shape SKIPPED, C1 all 12/12 / free 8/8 (results/calibration/PREREG-neiso72-hydro-ps-window-2026-07-31.md).", "file": "frontend/data/backcast/runs/2026-07-31-neiso-72-hy-window.js", "id": "2026-07-31-neiso-72-hy-window", "iso": "NEISO", "label": "neiso 72 hy window", "shorthand": "neiso-72-hy-window", "years": [2023, 2024, 2025]}, {"date": "2026-08-03", "definition": "miso-119 same-HEAD zero-delta control", "file": "frontend/data/backcast/runs/2026-08-03-miso-119a-control.js", "id": "2026-08-03-miso-119a-control", "iso": "MISO", "label": "miso 119a control", "shorthand": "miso-119a-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-03", "definition": "miso-119 single delta: gas_offer_margin_zonal_anchor=true on the miso-117b keeper", "file": "frontend/data/backcast/runs/2026-08-03-miso-119b-zonal-anchor.js", "id": "2026-08-03-miso-119b-zonal-anchor", "iso": "MISO", "label": "miso 119b zonal anchor", "shorthand": "miso-119b-zonal-anchor", "years": [2023, 2024, 2025]}, {"date": "2026-08-03", "definition": "miso-121 arm A CONTROL \u2014 zero-delta same-HEAD replay of the miso-117b keeper (PREREG-miso121 \u00a78.2)", "file": "frontend/data/backcast/runs/2026-08-03-miso-121a-control.js", "id": "2026-08-03-miso-121a-control", "iso": "MISO", "label": "miso 121a control", "shorthand": "miso-121a-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-03", "definition": "miso-121 arm B TREATMENT \u2014 dual_fuel_switching=true, single delta vs arm A (PREREG-miso121 \u00a78.2)", "file": "frontend/data/backcast/runs/2026-08-03-miso-121b-dual-fuel.js", "id": "2026-08-03-miso-121b-dual-fuel", "iso": "MISO", "label": "miso 121b dual fuel", "shorthand": "miso-121b-dual-fuel", "years": [2023, 2024, 2025]}, {"date": "2026-08-03", "definition": "PROMOTED TO NEISO KEEPER at caiso-159 (2026-08-03). Determination CALIBRATED-WITH-CAVEATS -- IDENTICAL to the neiso-72 incumbent on every criterion, every grade-summary field and the C1 headline (all 12/12, free 8/8). caiso-156 arm B (treatment): POST-FIX CT heat-rate artifact with the hour-grain physical-band screen applied, solved cold per ADDENDUM B against a same-HEAD control. NINE ScenarioConfig fields differ from the committed neiso72_hy_window_B keeper (caiso_firm_import_selfsched_clip, coal_prb_committed_split, crossover_solve_year_weather, demand_growth_vintage, ercot_dam_availability_gas_event_cap, gas_offer_margin_anchor_by_zone, gas_offer_margin_zonal_anchor, miso_coal_night_floor, pjm_rggi_allowance_pricing) and ALL NINE are schema drift, not a config change (CORRECTED 2026-08-03 by the calibration-keeper-auditor: originally miscounted as seven, omitting demand_growth_vintage and gas_offer_margin_anchor_by_zone): each was ADDED to ScenarioConfig after the neiso-72 solve, seven default to False and two (demand_growth_vintage, gas_offer_margin_anchor_by_zone) default to None, and this arm records every one at its class default. The delta is the CONTENT of the shared measured CT heat-rate artifact the keeper already consumes: scripts/data/derive_campd_ct_heat_rates.py declares a physical band [6.0, 25.0] MMBtu/MWh but applied it ONLY to the plant aggregate, so individual loaded hours at physically impossible heat rates -- a meter artifact, not generation behaviour -- were averaged into the plant rate and diluted it LOW (the caiso-146 section 2.4 defect). The screen now applies the module's OWN declared band per loaded hour and evaluates the _MIN_LOADED_HOURS trust gate on the in-band hours. ZERO NEW PARAMETERS and ZERO ScenarioConfig surface: cap percentile, loaded fraction, all-hours gross_mwh weights, parasitic conversion, the plant-aggregate flag and the flag=='ok' application rule are untouched.", "file": "frontend/data/backcast/runs/2026-08-03-neiso-caiso156-meter-screen.js", "id": "2026-08-03-neiso-caiso156-meter-screen", "iso": "NEISO", "label": "neiso caiso156 meter screen", "shorthand": "neiso-caiso156-meter-screen", "years": [2023, 2024, 2025]}, {"date": "2026-08-03", "definition": "pjm-151 arm B: PJM reference-price seam deliverability envelopes built PER-NEIGHBOUR from each seam's own ties (spec.PJM_TIE_NEIGHBOR) instead of summing a per-model-ZONE envelope over the neighbour's border_zones. Rule 14 [R-ACCURATE] internal-consistency repair of keeper-note item 12, off-queue as a NEW measured identification (rule 28a) -- the PJM price-formation frontier is owner-declared and this is not a price lever. ZERO new parameters: the tie->interface map is an identity read off PJM's own tie labels. Measured ex ante at p90: the legacy TVA export cap ran 124x/53x/40x the direct one and never bound, LGEE's 33x/42x/26x; the legacy LGEE import cap is 0 MW against a measured 518/539/549 MW, so the repair loosens as well as tightens. NYISO reproduces at 1.00x -- the control. Single delta vs keeper pjm147_chp_B: pjm_seam_envelope_by_neighbor=true", "file": "frontend/data/backcast/runs/2026-08-03-pjm-151-seam-envelope.js", "id": "2026-08-03-pjm-151-seam-envelope", "iso": "PJM", "label": "pjm 151 seam envelope", "shorthand": "pjm-151-seam-envelope", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "ercot-159 Run A: zero-delta control replay of the ercot158 keeper recipe (PRECOMMIT-ercot159 \u00a71; the ercot98 honest-inputs / ercot150-K2 same-HEAD-control pattern)", "file": "frontend/data/backcast/runs/2026-08-04-159-control-zerodelta.js", "id": "2026-08-04-159-control-zerodelta", "iso": "ERCOT", "label": "159 control zerodelta", "shorthand": "159-control-zerodelta", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "ercot-159 Run B: single delta ercot_energy_online_capability_cap=true on the ercot158 keeper recipe (queue item 9, ERCOT-155 successor; PRECOMMIT-ercot159 \u00a71-\u00a72)", "file": "frontend/data/backcast/runs/2026-08-04-159-energy-capability-cap.js", "id": "2026-08-04-159-energy-capability-cap", "iso": "ERCOT", "label": "159 energy capability cap", "shorthand": "159-energy-capability-cap", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "measured DLAP loss zones caiso166: LA_BASIN takes its own measured deviation at DLAP_SCE-APND and SDGE at DLAP_SDGE-APND, replacing the TH_SP15_GEN generation-hub stand-in. Rule 14 [R-ACCURATE] measured-over-reconciled upgrade on the caiso-165 intake; caiso_zonal_loss_surface is True in BOTH arms, so the only object that differs from the control is CAISO_loss_surface.csv.", "file": "frontend/data/backcast/runs/2026-08-04-caiso-166-measured-dlap.js", "id": "2026-08-04-caiso-166-measured-dlap", "iso": "CAISO", "label": "caiso 166 measured dlap", "shorthand": "caiso-166-measured-dlap", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "(CONTROL, not a candidate) caiso-172 Arm A. A SAME-HEAD, freshly solved baseline carrying the INCUMBENT residual-identified CAISO_TAC_ZONE_WEIGHTS['PGE-TAC'] = {NP15 0.86, ZP26 0.14}, so the measured arm's delta is attributable to the weight change and nothing else. It reproduces the then-incumbent keeper 2026-08-04-caiso-166-measured-dlap BIT-IDENTICALLY \u2014 max |dprice| = 0.000000 and max |ddemand| = 0.000000 over all P1 zone-hours of 2023/2024/2025 \u2014 which is what licenses reading the A/B delta as the mechanism's own effect. Determination CALIBRATED-WITH-CAVEATS, identical to the keeper criterion-for-criterion. Its ledger still carries the PGE-TAC entry as residual (n_residual 9); the measured arm 2026-08-04-caiso-172-measured-path15 closes it to 8.", "file": "frontend/data/backcast/runs/2026-08-04-caiso-172-control-pge.js", "id": "2026-08-04-caiso-172-control-pge", "iso": "CAISO", "label": "caiso 172 control pge", "shorthand": "caiso-172-control-pge", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "KEEPER (caiso-172, 2026-08-04). The MEASURED Path-15 split of PG&E TAC load: CAISO_TAC_ZONE_WEIGHTS['PGE-TAC'] moves from the 0.86/0.14 estimate of 'unverified provenance' \u2014 the LAST residual-identified member of that table (audit C-16, issue #1372) \u2014 to 0.883951/0.116049, derived by scripts/data/derive_caiso_path15_load_split.py from two PUBLISHED CAISO OASIS Atlas reports: ATL_LDF's per-pnode load distribution factors inside DLAP_PGAE-APND joined by substation to ATL_PNODE_MAP's authoritative TH_NP15_GEN / TH_ZP26_GEN membership (CAISO's own Path-15 geography). The estimate put 17% too much PG&E load in ZP26. ZERO free parameters and ZERO ScenarioConfig fields \u2014 a rule 14 [R-ACCURATE] measured-over-estimate substitution and a rule 20 [R-DOF] CLOSURE: n_residual 9 -> 8, CAISO's ISO-specific residual count 4 -> 3. Determination-NEUTRAL against its own same-head control (CALIBRATED-WITH-CAVEATS, 0 FAILs, same 2 ledgered caveats, same C3a +11.5%/+14.4%), so it costs nothing and buys a DOF. Quantity effect measured, not asserted: ZP26 served energy -17.11% and NP15 +2.79% in every year at ISO total unchanged; Path-15 N->S flow -13.2/-12.2/-12.0% (10.27->8.92, 12.19->10.70, 12.23->10.77 TWh). The NP15-ZP26 basis moves TOWARD the measured +5.947/+8.576/+5.727 $/MWh (+0.236->+0.333, +0.127->+0.217, +0.109->+0.179, i.e. 4.0->5.6%, 1.5->2.5%, 1.9->3.1% of measured) but KNOWN-OPEN 1 stays wide open and this was pre-registered as REPORTED, NOT GATED.", "file": "frontend/data/backcast/runs/2026-08-04-caiso-172-measured-path15.js", "id": "2026-08-04-caiso-172-measured-path15", "iso": "CAISO", "label": "caiso 172 measured path15", "market_story": "This run changes WHERE PG&E's load sits, not how any plant offers. PG&E's TAC area straddles Path 15, and the model had been putting 14% of it in ZP26 \u2014 the San Joaquin Valley between Path 15 and Path 26 \u2014 on a ratio nobody could source. CAISO's own published load distribution factors say 11.6%. The real market puts less load south of Path 15 than the model assumed, because the PG&E sub-LAPs that actually sit there (SLAP_PGZP and Kern) are agricultural and oil-field load, while the Bay Area, Sacramento Valley, Fresno and the Central Coast \u2014 the bulk of PG&E's customers \u2014 are north of the boundary. Moving 2.1-2.3 TWh/yr of demand from ZP26 to NP15 does exactly what physics says it should: the Path-15 north-to-south transfer that used to serve that load falls by ~1.4 TWh/yr and the link sits at its bound in fewer hours (2025: 21 -> 13). Prices barely move because neither zone was scarce at the margin \u2014 which is the honest result, and the reason this is filed as an input correction rather than a lever: it makes the load allocation true, and it does not pretend to close the north-south congestion basis, which remains 3-6% represented.", "shorthand": "caiso-172-measured-path15", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "caiso164 zonal loss surface: CAISO measured marginal delivery-factor surface (dev_z=sum(MCL_z)/sum(MCE) from CAISO's own published DAM component record) on the internal N-S links, one-way loss pairs. Rule 14 [R-ACCURATE] measured-over-estimate; the LP was lossless. Bounded ex ante at the measured dMCL (19.8/12.8/18.3% of the NP15-ZP26 basis); NOT a fix for the congestion majority.", "file": "frontend/data/backcast/runs/2026-08-04-caiso164-zonal-loss-surface.js", "id": "2026-08-04-caiso164-zonal-loss-surface", "iso": "CAISO", "label": "caiso164 zonal loss surface", "shorthand": "caiso164-zonal-loss-surface", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "control flagoff lossless baseline for caiso164: same-HEAD A/B control with caiso_zonal_loss_surface off, the model's default lossless internal network. Structurally single-field delta against the treatment arm.", "file": "frontend/data/backcast/runs/2026-08-04-control-flagoff-lossless-baseline.js", "id": "2026-08-04-control-flagoff-lossless-baseline", "iso": "CAISO", "label": "control flagoff lossless baseline", "shorthand": "control-flagoff-lossless-baseline", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "KEEPER (OWNER-PROMOTED 2026-08-04, ercot-165, arm B). DETERMINATION: NOT-YET \u2014 criterion-for-criterion IDENTICAL to the superseded ercot158 keeper (C1/C2/C4/C6/C8 PASS; C3a/C3b/C3c/C7 FAIL, the C7 failure the same pre-existing 2023-lignite cv-leg); nothing regresses (C3a 2023 -32.8% -> -32.6%, 2025 -8.1% -> -7.9%; C2 2025 gas -2.0% -> -1.7%). ONE mechanism, single delta off the ercot158 recipe: ercot_wtx_curtail_unpooled=true + ercot_wtx_panhandle_owner=\"share\" \u2014 unpooled diurnal-family curtailment shares (the pooled union saturated and broadcast the overnight family's shape onto the daytime/solar-flood family and onto the Panhandle interface) plus a single Panhandle-scoped measured share, so the interface has exactly one owner instead of two overlapping mechanisms (rule 19 R-ONE-MECH). [3e] wind curtailment model/reported: .951/.890/.787 (ercot158, mean abs err 0.124) -> 1.109/.974/.887 (0.083). HONEST LIMIT, CARRIED HERE AND IN THE ATTESTATION, NOT HIDDEN: the charter's SHAPE target is MISSED \u2014 2025 wind-curtailment hod corr only -0.077 -> -0.058 (still negative); afternoon mass 0.159 vs actual 0.222; overnight 0.357 -> 0.360 vs actual 0.266 (the added curtailment landed OVERNIGHT, a level re-centring effect, not the daytime-mode insight). 2023 moved from 5% UNDER- to 11% OVER-curtailment and solar volume is marginally worse. The daytime mode remains an OPEN ROOT-CAUSE ISSUE, not a calibrated behaviour. *** RE-SCORED 2026-08-05 (rubric v3.0, owner amendment, ERCOT-2023-diagnosis session): C3c FAIL -> CAVEAT [ledgered, ACCEPTED MODEL-CLASS LIMITATION] in all three years via the three owner-signed kind=model-class exceptions entries added to the bundle attestation (exhaustion record ercot-95/97/102/107/108/155/159/161/162/163; open residual lanes: storage AS-vs-energy split at scarcity, CC headroom identification). C6 now PASS (the promotion-day metrics.json predated the attestation generation - bookkeeping, not substance). Determination remains NOT-YET; basis narrowed to the 2023-only C3a (-32.6%) + C3b (NRMSE 0.610) FAILs and the C7 2023 COAL_LIGNITE cv-leg.", "file": "frontend/data/backcast/runs/2026-08-04-ercot165-unpooled-share.js", "id": "2026-08-04-ercot165-unpooled-share", "iso": "ERCOT", "label": "ercot165 unpooled share", "market_story": "WIND (West + Panhandle corridor): ERCOT's real West-Texas export corridor is limited by dozens of internal 138/345 kV Permian/CREZ elements the 8-zone reduction collapses into one wide pipe, so the LP would deliver wind the real grid could not move. The measured SCED binding incidence of those elements is the ceiling \u2014 and it is TWO populations, not one: a daytime/solar-flood family (peaks h14-15, tracks actual SOLAR curtailment +0.775..+0.959 every year) and an overnight wind-export family (peaks h21-23). Pooling them into one union saturates and hands the whole corridor the overnight family's shape, which is why the armed keeper cut deepest at night. Unpooled, each family's own measured incidence survives. PANHANDLE: the zone carries no load, so every MW it produces must clear the Panhandle->North interface; the measured PNHNDL enforcement incidence (2025 peak h10, day share 0.541) is what actually constrains it sub-limit, and it now owns that pressure alone instead of sharing it with a second, overnight-shaped broadcast on the same hours. GAS: the corridor wind the ceiling holds back is replaced by CC_REGULAR (+0.3..0.6 TWh/yr), which is the displacement ERCOT's own dispatch shows when the West is congested. HONEST LIMIT, not a market story: the model still under-curtails wind in the mid-afternoon hours (2025 afternoon mass 0.159 vs actual 0.222) \u2014 the daytime mode is a measured signal no armed mechanism reaches at the driver's two-scalar budget, and it is an open root-cause issue, not a calibrated behaviour.", "shorthand": "ercot165-unpooled-share", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "ercot-165 arm A: unpooled diurnal-family curtailment shares; PNHNDL owned by the endogenous tie (no driver ceiling on Panhandle).", "file": "frontend/data/backcast/runs/2026-08-04-ercot165-unpooled-tie.js", "id": "2026-08-04-ercot165-unpooled-tie", "iso": "ERCOT", "label": "ercot165 unpooled tie", "shorthand": "ercot165-unpooled-tie", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "(PROBE \u2014 A/B CONTROL, not a keeper) miso-122 arm A: a zero-delta, same-HEAD replay of the MISO keeper 2026-08-03-miso-117b-ct-heat on the PRE-scope-gate chp_power_only_heat_rates_MISO.csv (sha 4cbeb961...). BYTE-IDENTICAL to the keeper (max class-hour |delta| <= 1e-6 in all three years), same determination NOT-YET and the same nine criterion statuses, so it is a valid control for arm B. Exists only to isolate the arm-B delta; the delta between the arms is an INPUT FILE, not a ScenarioConfig key, so the two run_config.json blocks are identical by design. Evidence: PREREG/FINDING-miso122-hybrid-cogen-scope-gate-2026-08-03.md, _miso122_scope_gate_ab.json.", "file": "frontend/data/backcast/runs/2026-08-04-miso-122a-control.js", "id": "2026-08-04-miso-122a-control", "iso": "MISO", "label": "miso 122a control", "shorthand": "miso-122a-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "(PROBE \u2014 DISPATCH-LIVE / PRICE-INERT; promotion candidate NOT taken in-session) miso-122 arm B: the hybrid-cogen dark-fuel SCOPE GATE added to scripts/data/derive_chp_power_only_heat_rates.py. eGRID's plant-level CHP split cannot see a HYBRID cogen (a topping CC/CT train plus a direct-fired package boiler on one ORIS code), so 16.6 % of plant 55088 Dearborn's metered fuel \u2014 burned in three Other-boiler units with ZERO gross load \u2014 sat inside the topping rate charged to its CC_CHP (350 MW) and CT_CHP (165 MW) tranches, +16.6 % too dear. The gate removes it at CEMS unit grain: heat_rate = (PLHTIAN + CHPCHTI) * (1 - dark_fuel_share) / PLNGENAN, a SHARE not an MMBtu subtraction, zero free parameters, no threshold, strict no-op where absent. Applied rows: 55088 CC_CHP + CT_CHP 8.3465 -> 6.9573 (-16.6 %) and 10745 MCV 8.8243 -> 8.8160 (-0.09 %). RESULT: dispatch-live, price-inert \u2014 CC_CHP +0.36/+0.27/+0.52 TWh and CT_CHP +0.22 TWh/yr displacing CC_REGULAR, imports and COAL_PRB, but max zonal |dLMP| 0.049/0.039/0.075 $/MWh against a 0.10 pre-registered bar, so ZERO of three years clear it. Every gate passes (K1 artifact fidelity, K2 control byte-identity, K4 zero config delta, K5 span, K6 one-sided direction, P1-P6): nothing regresses, all nine criteria identical to the control, determination NOT-YET decided by the same C7 COAL_PRB shape FAIL this lever does not touch. Admissible on rule 14 [R-ACCURATE] ONLY and ships regardless of the residual. Evidence: FINDING-miso122-hybrid-cogen-scope-gate-2026-08-03.md, PREREG same date, _miso122_scope_gate_ab.json, PROBE-miso122-hybrid-cogen-scope-2026-08-03.txt.", "file": "frontend/data/backcast/runs/2026-08-04-miso-122b-scope-gate.js", "id": "2026-08-04-miso-122b-scope-gate", "iso": "MISO", "label": "miso 122b scope gate", "market_story": "CC_CHP / CT_CHP (+0.36/+0.27/+0.52 and +0.22 TWh): Dearborn Industrial Generation is an industrial cogen selling into MISO-East off a topping CC+CT train, and its steam host also runs three package boilers fired directly for process heat. Those boilers make no electricity, so their fuel is not a cost of Dearborn's power -- a real merchant offering this plant into the day-ahead market bids the turbine train's own fuel burn, not the steam-house's. Pricing the whole facility's fuel against its MWh made the plant look 16.6 % less efficient than it is and pushed it up the stack behind units it genuinely beats. Corrected, it clears where a real bidder would put it.\nCC_REGULAR (-0.19/-0.22/-0.31), import (-0.15/-0.11/-0.13) and COAL_PRB (-0.11/-0.06/-0.14): the mirror image, and the reason this is a re-ordering rather than an addition. A correctly-priced cogen displaces the marginal merchant combined cycle, the priced seam band and the PRB coal it now sits below -- which is exactly what a 515 MW efficiency correction should do to a stack, and why total system energy is unchanged.\nWhy price barely moves: 515 MW of re-ordering inside a ~100 GW market almost never changes the marginal unit. The demand-weighted lambda falls 0.03-0.06 $/MWh and no zone's lambda rises. That is the honest size of the effect and the run is not offered as a price-formation fix.", "shorthand": "miso-122b-scope-gate", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "miso-124: re-arm dual_fuel_switching on the current keeper (2026-08-04-miso-122b-scope-gate). Single-delta replay restoring the owner-authorized rule-1 [R-STRUCT] arming that miso-121 adjudicated and that was lost when miso-122 branched off the older miso-117b keeper. Verdict NOT re-adjudicated: the mechanism is measured, zero-free-parameter and PRICE-INERT in sample (~0.002 % of MISO energy, FINDING-miso121). Expected: identical determination, identical nine criterion statuses, C7 COAL_PRB the sole FAIL.", "file": "frontend/data/backcast/runs/2026-08-04-miso-124-dualfuel-rearm.js", "id": "2026-08-04-miso-124-dualfuel-rearm", "iso": "MISO", "label": "miso 124 dualfuel rearm", "shorthand": "miso-124-dualfuel-rearm", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "miso-126 arm B: SINGLE DELTA cc_steam_part_capacity=true on the MISO keeper 2026-08-04-miso-124-dualfuel-rearm, scored against the same-HEAD zero-delta control miso126_steampart_A. Restores EIA-860 55088 Dearborn ST1 (250.0 MW, prime mover CA, Unit Code SINT shared with the two NG CT turbines whose exhaust drives it, Energy Source 1 BFG) to the LP fleet as CC_CHP in MISO-East, at the eGRID plant heat rate its block siblings already carry. Rule 14 [R-ACCURATE] capacity-representation repair; NOT chartered as a C7/C3a/C3c instrument. Prereg results/calibration/PREREG-miso126-cc-steam-part-capacity-2026-08-04.md; all five properties verified before this solve. NOTE: this is the SECOND solve of arm B. The first was exactly inert because the flag was not forwarded at the BACKCAST's own copy of the bin synthesis (scripts/run_calibration.py) -- the nyiso-89 regression class the code comment at that site explicitly warns about. Fixed and re-solved; the bin synthesis now carries capacity_mw 600.0 at (55088, CC_CHP).", "file": "frontend/data/backcast/runs/2026-08-04-miso-126-steampart-b.js", "id": "2026-08-04-miso-126-steampart-b", "iso": "MISO", "label": "miso 126 steampart b", "shorthand": "miso-126-steampart-b", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "miso-126 arm A: same-HEAD ZERO-DELTA control replay of the MISO keeper 2026-08-04-miso-124-dualfuel-rearm at the miso-126 HEAD (cc_steam_part_capacity declared but DEFAULT OFF). Prereg KE5: this must reproduce the incumbent keeper's scorecard exactly -- determination, all nine criterion statuses, ledgered caveats and every legitimacy-diagnostic verdict. Every arm-B delta is quoted against THIS arm, never against the committed keeper (miso-124 DO-NOT-MISREAD: price response is not stable across keepers).", "file": "frontend/data/backcast/runs/2026-08-04-miso-126-steampart-control.js", "id": "2026-08-04-miso-126-steampart-control", "iso": "MISO", "label": "miso 126 steampart control", "shorthand": "miso-126-steampart-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "miso-127 arm B: coal_mustrun_online_pmin=true, single delta vs the same-HEAD control", "file": "frontend/data/backcast/runs/2026-08-04-miso-127-onlinepmin.js", "id": "2026-08-04-miso-127-onlinepmin", "iso": "MISO", "label": "miso 127 onlinepmin", "shorthand": "miso-127-onlinepmin", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "miso-127 arm A: same-HEAD zero-delta control for the coal_mustrun_online_pmin A/B", "file": "frontend/data/backcast/runs/2026-08-04-miso-127-onlinepmin-control.js", "id": "2026-08-04-miso-127-onlinepmin-control", "iso": "MISO", "label": "miso 127 onlinepmin control", "shorthand": "miso-127-onlinepmin-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "neiso-81 arm B: measured_chp_heat_rates ARMED on the corrected (miso-122 gate-3) NEISO artifact, single delta vs arm A. Re-adjudication of the neiso-70 'O' under the owner standing standard of 2026-08-04. Prereg: results/calibration/PREREG-neiso81-chp-heat-rate-readjudication-2026-08-04.md", "file": "frontend/data/backcast/runs/2026-08-04-neiso81-chpheatrate.js", "id": "2026-08-04-neiso81-chpheatrate", "iso": "NEISO", "label": "neiso81 chpheatrate", "shorthand": "neiso81-chpheatrate", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "nyiso-125 CONTROL: same-HEAD zero-delta replay of the nyiso-120 keeper recipe. Baseline for the nyiso_seam_deliverability_envelope single-delta A/B (PREREG-nyiso125-seam-envelope-2026-08-04.md).", "file": "frontend/data/backcast/runs/2026-08-04-nyiso-125-control.js", "id": "2026-08-04-nyiso-125-control", "iso": "NYISO", "label": "nyiso 125 control", "shorthand": "nyiso-125-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "nyiso-125 TREATMENT: nyiso_seam_deliverability_envelope=true. Single delta on the nyiso-120 keeper recipe. NYC (Zone J) and Long_Island (Zone K) border links follow NYISO's own measured p90 directional hourly seam envelope from the MIS P-32 posting; Upstate_West and Capital_Hudson keep their statics (refused on identification, PREREG section 2.3).", "file": "frontend/data/backcast/runs/2026-08-04-nyiso-125-seam-envelope.js", "id": "2026-08-04-nyiso-125-seam-envelope", "iso": "NYISO", "label": "nyiso 125 seam envelope", "shorthand": "nyiso-125-seam-envelope", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "pjm-152 arm A: the pjm-151 keeper recipe re-solved COLD at the collapsed HEAD. Rule 26 [R-DELETE] follow-up owed by pjm-151: pjm_seam_envelope_by_neighbor, the by_neighbor parameter, the zone-summed branch, the _CACHE_KEY_OPTIONAL_FIELDS / defaults-ledger / TIER_TAGS entries and the run_calibration.py plumbing are DELETED and the per-neighbour envelope construction is unconditional. NOT a mechanism change and NOT a lever: zero recipe deltas, and the collapse is proven rather than asserted -- the gate is max |dMW| = 0.000000 against results/calibration/pjm151_seam_B on every P1 class-hour of all three years. The collapse moves the cache key (an armed optional field was in the hash and the field is now gone), which is exactly why a cold re-solve is required instead of an assertion. Off-queue under rule 28(a): PJM's lever queue is EMPTY and its price-formation frontier is owner-declared (pjm-142); this is chartered debt discharge, not a successor.", "file": "frontend/data/backcast/runs/2026-08-04-pjm-152-collapse.js", "id": "2026-08-04-pjm-152-collapse", "iso": "PJM", "label": "pjm 152 collapse", "shorthand": "pjm-152-collapse", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "(A/B CONTROL, ercot-162) Fresh same-HEAD replay of the ercot158 keeper config UNCHANGED \u2014 the unconfounded base for the ercot162 storage RT offer-surface A/B (gap-hour mean $441.27 = the committed keeper to the cent). Arm run162b REFUTED.", "file": "frontend/data/backcast/runs/2026-08-04-run162a-storage-rt.js", "id": "2026-08-04-run162a-storage-rt", "iso": "ERCOT", "label": "run162a storage rt", "shorthand": "run162a-storage-rt", "years": [2023, 2024, 2025]}, {"date": "2026-08-04", "definition": "(PROBE \u2014 REJECTED, ercot-162) Measured multi-tranche battery RT discharge-offer surface (ercot_storage_rt_offer_surface): K=3 tranches per ERCOT battery unit at the measured PWRSTR absolute-$ SCED ladder, replacing the flat $10 battery_dispatch_adder (rule 19). R on multiple pre-registered kills: 2025 EIA-930 NG:BAT volume guard (discharge collapses ~74%/yr, \u221276% vs measured), zero-spurious mid-band tripped all 3 yrs, C3a/NRMSE degraded 2024/25; the 100-hour gap set lifts only $441\u2192$457 (+$16). A/B vs run162a. See FINDING-ercot162.", "file": "frontend/data/backcast/runs/2026-08-04-run162b-storage-rt.js", "id": "2026-08-04-run162b-storage-rt", "iso": "ERCOT", "label": "run162b storage rt", "shorthand": "run162b-storage-rt", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "caiso-174 Arm A CONTROL: the caiso-172 keeper recipe replayed at post-epoch main with storage_measured_base_fleet=FALSE. NOT a reconstruction of the pre-epoch keeper -- FFR-4D ALSO re-vintaged the constant STORAGE_BASE_FLEET_MW['CAISO'] 8,000 -> 15,450 MW (mid), which no flag gates, so this arm runs a FLAT 15,450 MW battery fleet in every year. It is the 'what if only the constant had been re-vintaged' counterfactual, and it isolates incidental code drift between the keeper's head 789e28b8 and this one so the Arm B delta is attributable to the per-year vintaging leg alone. See PRECHECK-caiso174 4a.", "file": "frontend/data/backcast/runs/2026-08-05-caiso-174-control-flatfleet.js", "id": "2026-08-05-caiso-174-control-flatfleet", "iso": "CAISO", "label": "caiso 174 control flatfleet", "shorthand": "caiso-174-control-flatfleet", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "caiso-174 Arm B TREATED: the caiso-172 keeper recipe replayed at post-epoch main with storage_measured_base_fleet at its shipped default (TRUE). THE RE-SOLVE OWED BY FFR-4D section 7 D-2 under cache epoch 2026-08-04c. The CAISO backcast now resolves its battery base fleet AS OF THE SOLVE YEAR from EIA-860 (7,492.4 / 11,131.3 / 15,448.4 MW at year-end 2023/2024/2025) instead of a flat forecast base-year scalar, and storage_vintage_ramp -- armed on this recipe but a DEAD FLAG for batteries while the fleet was a scalar -- is live for batteries for the first time (2-D (6,8760) power-cap profile, verified before any price was read by scripts/probes/_caiso174_fleet_gate.py). Zero free parameters; rule 14 [R-ACCURATE] measured-over-estimate.", "file": "frontend/data/backcast/runs/2026-08-05-caiso-174-measured-fleet.js", "id": "2026-08-05-caiso-174-measured-fleet", "iso": "CAISO", "label": "caiso 174 measured fleet", "shorthand": "caiso-174-measured-fleet", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "CONTROL (ercot-168 A-side) - fresh same-HEAD replay of the ercot167 keeper recipe (2026-08-05-run167b-soc-reserve, bundle ercot167_socreserve_B), config UNCHANGED, full span 2023-2025, solved in-container against regenerated clean inputs (gtc-limits re-curated from the committed NP6-86 raw archives). Doubles as the regenerated-input drift measurement vs the committed keeper: drift ~zero (C3a -32.24 vs -32.2, C3b 0.6026 vs 0.603, tail 61/25/3, spurious 3/7/1, shed 4/2/0, D-1 identical incl. the sole failing row 2023 COAL_LIGNITE cv 0.331 / r 0.897). The A-side baseline for the ercot-168 pre-registered gate table (PRECOMMIT-ercot168-coal-perplant-year-curves-2026-08-05.md); the B-side arm 2026-08-05-run168b-year-curves was promoted keeper. Unattested by design (control replay; determination NOT-YET, governance UNATTESTED).", "file": "frontend/data/backcast/runs/2026-08-05-ercot168-control.js", "id": "2026-08-05-ercot168-control", "iso": "ERCOT", "label": "ercot168 control", "shorthand": "ercot168-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "miso-132(b) arm B: CC committed-band measured re-grounding \u2014 offer_curve_by_group CC_REGULAR.committed 1.20 -> 1.005 and CC_INTERMEDIATE.committed 0.92 -> 1.005, the fleet's own measured avg_committed_p50 (n=103, cap-weighted, miso_campd_marginal_hr_summary.csv). Rule-14 [R-ACCURATE] proxy-for-measurand swap, zero free parameters. PREREG-miso132b-cc-committed-band-regrounding-2026-08-05.md \u00a73+\u00a75; scored against same-HEAD zero-delta control miso132_ccmin_A.", "file": "frontend/data/backcast/runs/2026-08-05-miso-132b-cc-committed.js", "id": "2026-08-05-miso-132b-cc-committed", "iso": "MISO", "label": "miso 132b cc committed", "shorthand": "miso-132b-cc-committed", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "miso-132(b) arm A: same-HEAD zero-delta control replay of keeper 2026-08-04-miso-127-onlinepmin (PREREG-miso132b-cc-committed-band-regrounding-2026-08-05.md \u00a73). No override; control for the CC committed-band measured re-grounding A/B.", "file": "frontend/data/backcast/runs/2026-08-05-miso-132b-control.js", "id": "2026-08-05-miso-132b-control", "iso": "MISO", "label": "miso 132b control", "shorthand": "miso-132b-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "NEISO 2022 VALIDATION TOUCHPOINT (rule 22, validation tier). Byte-faithful replay of the neiso-83 keeper recipe (2026-08-05-neiso-83-ca1-reclass, CALIBRATED-WITH-CAVEATS) on the held-out 2022 year. Frozen recipe, zero deltas: no parameter was tuned for, against, or in response to 2022. Iterable model-SELECTION evidence, NEVER a certified out-of-sample skill number. NEISO's locked test (2019 + H1-2026) is NOT touched here. [CORRECTED 2026-08-06, owner decision D-23: this previously read \"is SPENT and is NOT re-opened here\". NEISO's locked test has NEVER BEEN GRANTED and has never been run - no 2019 or H1-2026 year has ever been solved, scored or registered for this ISO. This run's own posture is unchanged: a VALIDATION-tier 2022 spend only. Citation chain: results/calibration/ASSESSMENT-neiso87-declaration-2026-08-06.md section 1 -> docs/third-party-peer-review-2026-07.md section 6.3 item 1 -> D-23 / sitting Addendum X.6.] Spent under a narrow owner lift of the 2026-07-25 holdout freeze, which is re-armed in the same session.", "file": "frontend/data/backcast/runs/2026-08-05-neiso-2022-touchpoint.js", "id": "2026-08-05-neiso-2022-touchpoint", "iso": "NEISO", "label": "neiso 2022 touchpoint", "shorthand": "neiso-2022-touchpoint", "years": [2022]}, {"date": "2026-08-05", "definition": "neiso-83 arm B: cc_steam_part_reclass ARMED on the 2026-08-04-neiso81-chpheatrate keeper recipe, single delta vs arm A. NEISO 6081 Stony Brook CA1 (96.0 MW) re-classed from standalone oil onto the CC_REGULAR block it is the steam half of. Zero fitted parameters. Prereg: results/calibration/PREREG-neiso83-stonybrook-ca1-2026-08-05.md", "file": "frontend/data/backcast/runs/2026-08-05-neiso-83-ca1-reclass.js", "id": "2026-08-05-neiso-83-ca1-reclass", "iso": "NEISO", "label": "neiso 83 ca1 reclass", "shorthand": "neiso-83-ca1-reclass", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "neiso-83 arm A: same-HEAD ZERO-DELTA control of the 2026-08-04-neiso81-chpheatrate keeper. No --set. Baseline for the cc_steam_part_reclass A/B (miso-124: price response is not stable across keepers, so the committed keeper is not an admissible baseline). Prereg: results/calibration/PREREG-neiso83-stonybrook-ca1-2026-08-05.md", "file": "frontend/data/backcast/runs/2026-08-05-neiso-83-control-zerodelta.js", "id": "2026-08-05-neiso-83-control-zerodelta", "iso": "NEISO", "label": "neiso 83 control zerodelta", "shorthand": "neiso-83-control-zerodelta", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "nyiso-127 CONTROL: same-HEAD replay of the nyiso-125 keeper recipe. Pairs with nyiso127_par_B (single delta: nyiso_seam_par_attribution). K6 requires this arm reproduce the keeper's C3a to +/-0.2pp.", "file": "frontend/data/backcast/runs/2026-08-05-nyiso-127-control.js", "id": "2026-08-05-nyiso-127-control", "iso": "NYISO", "label": "nyiso 127 control", "shorthand": "nyiso-127-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "nyiso-127 TREATMENT: nyiso_seam_par_attribution=true. Rebuild ALL FOUR NYISO_external border-link caps from the measured MIS P-32 per-neighbour schedules, attributing each posted row to its Gold Book tie-landing zone and splitting SCH - PJ - NY by NYISO's published NY-NJ PAR percentages under published PAR availability (MIS P-33 outSched). SUPERSEDES nyiso_seam_deliverability_envelope (rule 19), set false so run_config reads honestly; the code enforces exclusivity with if/elif, so this is a SINGLE behavioural delta. Zero free parameters, n_residual unchanged at 6. Pre-registration: PREREG-nyiso126 + nyiso-127 addenda 1 and 2.", "file": "frontend/data/backcast/runs/2026-08-05-nyiso-127-par-attribution.js", "id": "2026-08-05-nyiso-127-par-attribution", "iso": "NYISO", "label": "nyiso 127 par attribution", "shorthand": "nyiso-127-par-attribution", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "PJM 2022 VALIDATION TOUCHPOINT (rule 22, validation tier). Byte-faithful replay of the pjm-152 keeper recipe (2026-08-04-pjm-152-collapse, CALIBRATED) on the held-out 2022 year. Frozen recipe, zero deltas: no parameter was tuned for, against, or in response to 2022. Iterable model-SELECTION evidence, NEVER a certified out-of-sample skill number. Spent under a narrow owner lift of the 2026-07-25 holdout freeze, which is re-armed in the same session.", "file": "frontend/data/backcast/runs/2026-08-05-pjm-2022-touchpoint.js", "id": "2026-08-05-pjm-2022-touchpoint", "iso": "PJM", "label": "pjm 2022 touchpoint", "shorthand": "pjm-2022-touchpoint", "years": [2022]}, {"date": "2026-08-05", "definition": "A/B CONTROL (ercot-167): fresh same-HEAD full-span replay of the ercot165 keeper config, UNCHANGED (the ercot150-K2 discipline - the control is never the committed keeper bundle, so regenerated-input/env drift cancels A->B; the GTC clean partition was regenerated in-container from the committed raw archives before any full-span solve). Control for the storage AS SOC-reservation arm 2026-08-05-run167b-soc-reserve. Gates and verdict: results/calibration/FINDING-ercot167-storage-soc-reserve-ab-2026-08-05.md; docs/PRECOMMIT-ercot167-storage-as-soc-reserve-2026-08-05.md.", "file": "frontend/data/backcast/runs/2026-08-05-run167a-soc-control.js", "id": "2026-08-05-run167a-soc-control", "iso": "ERCOT", "label": "run167a soc control", "shorthand": "run167a-soc-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "KEEPER (OWNER-PROMOTED 2026-08-05, ercot-167, on the standing structural standard - the session's own pre-registered A/B verdict was REJECTED-AS-ARMED and is carried here openly). DETERMINATION: NOT-YET - C1/C2/C4/C6/C8 PASS; C3c LEDGERED CAVEAT x3 (rubric-v3.0 model-class entries, magnitudes 61/181, 25/53, 3/31); FAILs: C3a 2023-only -32.2% (ercot165 -32.6%), C3b 2023 0.603 + 2024 0.206 (NEW, +0.006 over the band - the maintenance-season spike-day root), C7 2023 COAL_LIGNITE cv 0.331 (r 0.897 passes). ONE mechanism, single delta off the ercot165 recipe: ercot_storage_as_soc_reserve=true - battery SOC floored at the MEASURED AS award x the PUBLISHED per-product SOC duration (Nodal Protocols 3.17.3), per-product shares from the 60-Day corpus, one award basis with the storage_as_commitment power dock (rule 19), deployment-netted, pin-reachability-clipped; ZERO new DOF (n_entries 11->12, n_residual 6). 2023 (the owner's separate-test year) passed EVERY pre-registered gate: scarcity-hour discharge 666->520 MW vs the SCED-measured actual 423, spurious 4->3, shed 4->4, tail 58->61 (+3 real). 2025 evening net-discharge lands on the 930-BAT actual (18h 3,033 vs 2,995; control +462 over), C3a 2025 -1.5->-0.8%. HONEST LIMITS: hub-basis 2024 C3a +1.4pp and one 2025 spurious hour ($43 graze at 2025-10-21 19h, adjacent to two newly-captured REAL tail hours) fired the precommit kills; the whole 2024 movement concentrates on the KNOWN fabricated-spike days (Apr 27/May 7/Nov 9 - FINDING-ercot166 s5, open root-cause, handoff H4 item 4); standing expectation: re-gate the identical arm after that defect lands. A/B control: 2026-08-05-run167a-soc-control. Full record: results/calibration/FINDING-ercot167-storage-soc-reserve-ab-2026-08-05.md.", "file": "frontend/data/backcast/runs/2026-08-05-run167b-soc-reserve.js", "id": "2026-08-05-run167b-soc-reserve", "iso": "ERCOT", "label": "run167b soc reserve", "market_story": "STORAGE: ERCOT batteries clear most of their value as ancillary services - the measured 60-Day awards run 1.25 GW (2023) to 2.8 GW (2025) of RegUp/RRS/ECRS/NonSpin - and ERCOT Nodal Protocols 3.17.3 obliges an ESR to HOLD STATE OF CHARGE backing every award for the product's duration. The real fleet therefore walks into the scarcity evening with most of its tank pledged: at the 61 actual >$1000 hours of 2023 it held 2,125 MW of awards = 2,705 MWh frozen of its ~4.1 GWh and discharged only 423 MW (delivery-2023 SCED telemetry). The energy-only LP saw the power dock but not the energy pledge, so it drained the whole tank into the peak (666 MW there; 2025 evening +462 to +1,268 MW over the 930-BAT actual). With the SOC backing floored at award x published duration, model discharge at 2023 scarcity falls to 520 MW and the 2025 evening net-discharge lands on the measured shape (18h 3,033 vs actual 2,995). GAS: the withheld battery energy is replaced at the margin by CC/CT dispatch in the same evenings - the direction ERCOT's own scarcity-hour composition shows (the model ran -1.9 GW of gas vs actual in those hours). AS deployment: the measured award DRAW-DOWN at the net-load ramp (the armed deployment floor) still releases both the power and - now - the energy behind it, so ramp co-participation is preserved, not stacked (rule 19).", "shorthand": "run167b-soc-reserve", "years": [2023, 2024, 2025]}, {"date": "2026-08-05", "definition": "KEEPER (OWNER-PROMOTED 2026-08-05, ercot-168, the owner's one-word 'Promote' directive on the fully-surfaced all-gates-green A/B record). DETERMINATION: NOT-YET - C1/C2/C4/C6/C8 PASS, C7 PASS (NEWLY CLOSED - the fail set shrinks {C3a,C3b,C7} -> {C3a,C3b}); C3c LEDGERED CAVEAT x3 (rubric-v3.0 model-class entries, counts UNCHANGED by the arm: 61/181, 25/53, 3/31); FAILs: C3a 2023 -32.2%, C3b 2023 0.604 + 2024 0.206 (both carried from the ercot167 recipe - the arm moves C3b-2023 +0.0017 and touches nothing else). ONE mechanism, single delta off the ercot167 keeper recipe: coal_perplant_offer_yearly=true (matrix 5.1 item 12, owner-adjudicated OPTION A) - the armed coal_perplant_offer_curves re-identified PER-YEAR for 2023 from the delivery-2023 60-Day SCED corpus (ercot-157 re-upload dissolves ERCOT-143's 'no 2023 SCED exists' closure premise); same modal derive, fed the year's own rows; ZERO new DOF (n_entries 12->13 measured-physical, n_residual unchanged at 6); no commodity backing claimed - the repricing is conduct, not commodity. MEASURED EFFECT: the LP two-shifts Oak Grove through price formation exactly as SCED did (overnight top $60.26/Oct $61.46 vs ~$20 overnight LMPs, backed to the mustrun floor; the Aug 15-19 scarcity-night pause reproduces endogenously). C7 2023 COAL_LIGNITE cv_ratio 0.331 -> 1.193 (gate >=0.5), profile_r 0.897 -> 0.976; COAL_PRB improves 0.737 -> 0.958; D-1 failing rows 1 -> 0. ALL SEVEN pre-registered gates GREEN (PRECOMMIT committed before any solve, no amendment needed): G-BIT 2024+2025 byte-identical A->B, G-SPUR 3->3, G-SHED 4->4, tail counts 61/25/3 UNCHANGED (deep inframarginal in every actual tail hour). CARRIED HONEST LIMIT: C3b-2024 0.206 crosses its <=0.20 band by 0.006 on the maintenance-season spike-day root (handoff H4 item 4, open root-cause issue). A/B control: 2026-08-05-ercot168-control. Full record: results/calibration/FINDING-ercot168-coal-perplant-year-curves-2026-08-05.md + docs/PRECOMMIT-ercot168-coal-perplant-year-curves-2026-08-05.md.", "file": "frontend/data/backcast/runs/2026-08-05-run168b-year-curves.js", "id": "2026-08-05-run168b-year-curves", "iso": "ERCOT", "label": "run168b year curves", "market_story": "COAL_LIGNITE / COAL_PRB (2023): the real Luminant/sub-bit coal fleet two-shifted overnight in Aug-Oct 2023 - Oak Grove submitted a $60-class overnight RT offer top (measured 60-Day SCED, $60.26/$61.46) against ~$20 overnight LMPs, so SCED base-pointed the units to LSL every ordinary night and restored full output for the day; Martin Lake's +$1.9 Aug level step crossed the ~$21.3 overnight LMP and carries the sub-bit two-shift at the margin. The model now prices those measured year-2023 curves directly (verbatim submitted conduct, zero fitted parameters), so the LP's own dispatch reproduces the overnight backdown, the daytime recovery, and the Aug 15-19 scarcity-night pause (those nights priced >> $60) - price formation, not a floor, and no forced energy: the mustrun block stays owned by the ERCOT-137 measured margin, the peak tranche by ERCOT-140's gas-parity margin.", "shorthand": "run168b-year-curves", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "caiso-175 Arm A CONTROL: the caiso-174 keeper recipe replayed at THIS head on the AS-COMMITTED CAISO TAC load series (five areas, MWD-TAC absent; 2023 covering 744 of 8760 hours). Establishes the incidental-code-drift baseline against which Arm B's demand-input correction is attributed, so the delta cannot be misread as drift between head ae7658d0 and this one.", "file": "frontend/data/backcast/runs/2026-08-06-caiso-175-control-tacbase.js", "id": "2026-08-06-caiso-175-control-tacbase", "iso": "CAISO", "label": "caiso 175 control tacbase", "shorthand": "caiso-175-control-tacbase", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "caiso-175 Arm B TREATED: the caiso-174 keeper recipe replayed at THIS head on the CORRECTED CAISO TAC load series. Two rule-14 [R-ACCURATE] demand-input corrections, zero free parameters: (1) MWD-TAC, the sixth CAISO-internal SLD_FCST area, is intaken and mapped 1:1 onto SP15_rest (it was omitted from postprocess_oasis_downloads.CAISO_TACS, so load_zonal_shares re-apportioned its 119/172/144 MW pro rata across the other four TACs -- caiso-172 s1.1 opened this, caiso-173 sC measured it at 0.24-0.30 pct of ISO load misplaced north of Path 15); (2) the 2023 series, which covered only 744 of 8760 hours (Jan-2023 only) so 91.5 pct of the year ran on a FLAT January-average zonal split, is completed to 8759 hours. Byte-faithful on every pre-existing row: max |delta| 0.000000 MW, 0 rows differing.", "file": "frontend/data/backcast/runs/2026-08-06-caiso-175-tac-intake.js", "id": "2026-08-06-caiso-175-tac-intake", "iso": "CAISO", "label": "caiso 175 tac intake", "shorthand": "caiso-175-tac-intake", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "FFR-7B Arm 1 paired-control ARM (Addendum D): the caiso-175 keeper recipe replayed at the Arm-1 commits (corrected statutory RPS constants: RPS plateaus at the statutory 60% per Pub. Util. Code \u00a7399.15(b)(2)(C); eligible set gains geothermal/biomass/offshore wind per \u00a725741(a), small hydro \u226430 MW excluded as misaligned to the aggregated hydro class). BYTE-IDENTICAL to the same-head control at base a9e1d084: 22/22 parquet outputs sha256-equal (control ffr7b_arm1_caiso_ctrl; hash table in results/calibration/_ffr7b_arm1_ab_compare.json). Determination reproduces the keeper verbatim (CALIBRATED-WITH-CAVEATS: C3a, C3c). NOT a keeper candidate - a rule-14 input-correction verification run.", "file": "frontend/data/backcast/runs/2026-08-06-caiso-177-ffr7b-arm1.js", "id": "2026-08-06-caiso-177-ffr7b-arm1", "iso": "CAISO", "label": "caiso 177 ffr7b arm1", "shorthand": "caiso-177-ffr7b-arm1", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "neiso-86: NEISO 2022 re-solved on the CORRECTED measured ISO-NE MA gas-basis input (neiso-86 intake). Exact replay of the neiso2022_touchpoint recipe; the ONLY difference is the repaired data. Owner narrow freeze lift 2026-08-06.", "file": "frontend/data/backcast/runs/2026-08-06-neiso-2022-corrected-basis.js", "id": "2026-08-06-neiso-2022-corrected-basis", "iso": "NEISO", "label": "neiso 2022 corrected basis", "shorthand": "neiso-2022-corrected-basis", "years": [2022]}, {"date": "2026-08-06", "definition": "FFR-7B Arm 1 paired-control ARM (Addendum D): the neiso-83 keeper recipe replayed at the Arm-1 commits (corrected statutory RPS constants: trajectory re-derived as the per-state NEW-renewable Class I/RES blend .29/.40/.48/.50 replacing the nuclear-counting CES blend; offshore wind added to the eligible set per 225 CMR 14.05). BYTE-IDENTICAL to the same-head control at base a9e1d084: 28/28 parquet outputs sha256-equal (control ffr7b_arm1_neiso_ctrl; hash table in results/calibration/_ffr7b_arm1_ab_compare.json). Determination reproduces the keeper verbatim (CALIBRATED-WITH-CAVEATS: C3c). NOT a keeper candidate - a rule-14 input-correction verification run.", "file": "frontend/data/backcast/runs/2026-08-06-neiso-84-ffr7b-arm1.js", "id": "2026-08-06-neiso-84-ffr7b-arm1", "iso": "NEISO", "label": "neiso 84 ffr7b arm1", "shorthand": "neiso-84-ffr7b-arm1", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "neiso-87 arm A: same-HEAD zero-delta control of the 2026-08-05-neiso-83-ca1-reclass keeper recipe, current committed gas basis (NEISO,2025,8 = +0.04 interpolation). Baseline for the Aug-2025 measured-basis A/B.", "file": "frontend/data/backcast/runs/2026-08-06-neiso-87-control.js", "id": "2026-08-06-neiso-87-control", "iso": "NEISO", "label": "neiso 87 control", "shorthand": "neiso-87-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "nyiso-128 CONTROL, and the DESIGNATED NYISO KEEPER from 2026-08-06. Arms NOTHING new: it is the superseded 2026-08-04-nyiso-125-seam-envelope keeper's OWN recipe re-solved on current main, with all 680 scenario_config fields verified identical to the incumbent before the solve (scripts/probes/_nyiso128_solve_ab.py --verify-only). It exists as the single-delta baseline for the nyiso_solar_market_generator_basis A/B and became the keeper because the re-solve alone lifts the determination NOT-YET -> CALIBRATED-WITH-CAVEATS: C3a PASSES all three years at +6.2 / -1.7 / -7.0 % against the incumbent's recorded +7.7 / -0.8 / -10.2 %, whose 2025 FAIL was the sole blocker. C3c stays the single ledgered caveat (2024 only, model 2 h vs RT actual 12 h, 0.17x under-produced); C1/C2/C3b/C4/C6/C7/C8 all PASS. The movement without a mechanism change is attributed to main's advance since the incumbent's git_sha 49aac023 plus nyiso-106's solar benchmark repair, which its own finding says applies from the next NYISO solve \u2014 an improved baseline after fixes land, ruled by the owner 2026-08-06 to need no deep diagnosis.", "file": "frontend/data/backcast/runs/2026-08-06-nyiso-128-control.js", "id": "2026-08-06-nyiso-128-control", "iso": "NYISO", "label": "nyiso 128 control", "shorthand": "nyiso-128-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "THE DESIGNATED NYISO KEEPER from 2026-08-06 (promoted nyiso-129). Arms exactly one field over the 2026-08-06-nyiso-128-control baseline: nyiso_solar_market_generator_basis, a rule 14 [R-ACCURATE] INPUT REPAIR with ZERO free parameters (n_residual unchanged at 6) that takes NYISO solar capacity from NYISO's own Gold Book Table III-2a 'NYISO Market Generators' registry (15 units, 573.4 MW; published load zone, nameplate MW and in-service date, crosswalked by the existing A-K -> five-zone map and ramped by the same month-of-commercial-operation construction the EIA-860 path applies) instead of the EIA-860 utility-scale operable schedule. THE DEFECT IT CORRECTS IS A DOUBLE COUNT: EIA-860's NY population lists every NY solar plant >= 1 MW, including ~2 GW of distribution-connected NY-Sun community solar that is not a NYISO market generator and whose output is ALREADY NETTED OUT of the EIA-930 NYIS demand series the model uses as load (NYIS 'NG: SUN' identically zero, 8,760/8,760 h) \u2014 so the same MWh was counted once as reduced demand and once as supply. Model capacity 1,645 / 2,566 / 2,930 MW becomes the registered 174.4 / 573.4 / 573.4 MW. RESULT: C3a PASSES all three years and improves where it was furthest out, +6.2 / -1.7 / -7.0 % -> +8.8 / +0.8 / -3.2 %; C1/C2/C3b/C4/C6/C8 PASS; the removed solar is replaced by IN-STATE THERMAL, not imports (JJA h16-h18 2025 CT_PEAKER +109 MW, ST_GAS +365 MW, CC_REGULAR +142 MW against solar -1,218 MW; import p50 +52 / 0 / +42 MW). DETERMINATION: CALIBRATED-WITH-CAVEATS (re-verified 2026-08-06 at nyiso-130, committed artifacts only, no solve). C3c is the SOLE non-passing criterion and is carried as a LEDGERED CAVEAT in all three years. The C3c-2023 miss is recorded at FULL magnitude \u2014 model 22 h vs RT actual 10 h, 2.20x OVER-produced, +12 h \u2014 and it is an in-training miss of the OPPOSITE sign to the inherited 2024 under-production caveat, so it carries its OWN correctly-signed classification and does NOT ride under that entry. nyiso-129 WITHHELD this exception for exactly that reason; nyiso-130 wrote it under an explicit owner authorization given in session, verbatim: 'After this run if the only outstanding issue is c3c scarcity tail of +12 hours in 2023 I want NYISO registered as calibrated with caveats. C3c is an acceptable gate failure as a ledgered caveat.' The withheld block is PRESERVED as _withheld_exception_history so the record shows the exception was AUTHORIZED, not quietly widened. THE LANE IS NOT CLOSED: nyiso-130 identified the over-production's owner \u2014 100 % of the modelled C3c tail in ALL THREE years is Long Island, inside HB14-21, with both Zone-K import paths at their bound \u2014 and TESTED the fix (arming NYISO's published 940 MW N-1-1 transfer limit in place of the loss-of-source-net 275/325 MW), which was REJECTED by its own pre-registered kill gate K6. Promoted anyway on rules 1 [R-STRUCT] / 14 [R-ACCURATE] under the owner's standing structure-over-gates standard, re-given verbatim in session nyiso-129: 'If structural integrity improves but gates regress that may still be a keeper.' nyiso-129 localized the whole C3c-2023 tail to Long Island (all 22 hours Zone K, h14-h19, Aug-21 + the Sept 4-9 heat wave), where the arm removes 97.7 of 152.1 MW \u2014 rule 14's own reading: the phantom solar was masking an over-tight Long Island representation, now the ISO's named successor lever. Evidence: results/calibration/FINDING-nyiso129-solar-basis-promotion-and-cf-successor-2026-08-06.md, FINDING-nyiso128-market-solar-basis-2026-08-06.md, PREREG-nyiso128-market-solar-basis-2026-08-05.md.", "file": "frontend/data/backcast/runs/2026-08-06-nyiso-128-solar-basis.js", "id": "2026-08-06-nyiso-128-solar-basis", "iso": "NYISO", "label": "nyiso 128 solar basis", "shorthand": "nyiso-128-solar-basis", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "FFR-7B Arm 1 paired-control ARM (Addendum D): the nyiso-125 keeper recipe replayed at the Arm-1 commits (corrected statutory RPS constants: renewable tier plateaus at 0.70 per PSL \u00a766-p(2)(a); eligible set gains existing hydro + offshore wind per \u00a766-p(1)(b)). BYTE-IDENTICAL to the same-head control at base a9e1d084: 25/25 parquet outputs sha256-equal (control ffr7b_arm1_nyiso_ctrl, not registered separately; full hash table in results/calibration/_ffr7b_arm1_ab_compare.json). Zero backcast contact proven: the constants' only consumers are gated on rps_enabled, which the calibration config hard-sets False. Determination reproduces the keeper verbatim (NOT-YET, price_mean; C3c ledger carried). NOT a keeper candidate - a rule-14 input-correction verification run.", "file": "frontend/data/backcast/runs/2026-08-06-nyiso-129-ffr7b-arm1.js", "id": "2026-08-06-nyiso-129-ffr7b-arm1", "iso": "NYISO", "label": "nyiso 129 ffr7b arm1", "shorthand": "nyiso-129-ffr7b-arm1", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "Calibration run from bundle nyiso130_control.", "file": "frontend/data/backcast/runs/2026-08-06-nyiso-130-control.js", "id": "2026-08-06-nyiso-130-control", "iso": "NYISO", "label": "nyiso 130 control", "shorthand": "nyiso-130-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "Calibration run from bundle nyiso130_n11tsl.", "file": "frontend/data/backcast/runs/2026-08-06-nyiso-130-n11-tsl.js", "id": "2026-08-06-nyiso-130-n11-tsl", "iso": "NYISO", "label": "nyiso 130 n11 tsl", "shorthand": "nyiso-130-n11-tsl", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "pjm-158 CONTROL: pjm-152 keeper recipe replayed at HEAD (unchanged, pjm_da_virtual_bids=True). Paired arm of the pre-registered DA-virtual A/B, PREREG-pjm158-da-virtual-clearing-2026-08-05.md.", "file": "frontend/data/backcast/runs/2026-08-06-pjm-158-control-virtual.js", "id": "2026-08-06-pjm-158-control-virtual", "iso": "PJM", "label": "pjm 158 control virtual", "shorthand": "pjm-158-control-virtual", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "pjm-158 TREATMENT: pjm-152 keeper recipe with pjm_da_virtual_bids DISARMED, single delta vs pjm158_ctl_A. Pre-registered A/B, PREREG-pjm158-da-virtual-clearing-2026-08-05.md.", "file": "frontend/data/backcast/runs/2026-08-06-pjm-158-novirtual-disarmed.js", "id": "2026-08-06-pjm-158-novirtual-disarmed", "iso": "PJM", "label": "pjm 158 novirtual disarmed", "shorthand": "pjm-158-novirtual-disarmed", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "A/B CONTROL for ercot-173 (the run168b keeper recipe, fresh same-HEAD replay; zero delta). ALSO the measured record that the run168b keeper NO LONGER REPRODUCES at current main (the nyiso-128 K6-class condition, now measured on ERCOT): vs the committed keeper sidecars this same-recipe replay reads C3a-2023 -22.5% vs -23.7% committed (mean basis), 2023 model>\\$200 tail 66 vs the ledgered 61, 2023 spurious mid-band 10 vs the ledgered 3, and a FIFTH 2023 shed hour (4098 = Jun-20 18:00) the committed keeper does not have; 2024 spurious 13 vs 7. Root: main moved under the keeper (dc10345c -> 82765525 spans LP rows/runner/RPS changes) plus in-container regenerated clean inputs. The ercot-173 A/B is scored strictly on this same-HEAD pair, so the arm deltas are clean; the keeper-reproduction drift is surfaced as its own finding (FINDING-ercot173). NOTE: the FIRST control attempt was discarded unregistered - the working tree was rebased mid-solve (dc10345c -> 82765525) making it not same-HEAD with the arm; this re-run replaced it. Full record: results/calibration/FINDING-ercot173-event-cap-reconciliation-2026-08-06.md.", "file": "frontend/data/backcast/runs/2026-08-06-run173a-reconc-control.js", "id": "2026-08-06-run173a-reconc-control", "iso": "ERCOT", "label": "run173a reconc control", "shorthand": "run173a-reconc-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-06", "definition": "(PROBE) REJECTED-AS-ARMED on three pre-registered non-renegotiable gates (PRECOMMIT-ercot172 \u00a75 inherited verbatim via PRECOMMIT-ercot173 \u00a75). Single delta off the run168b keeper recipe: ercot_dam_availability_event_cap_reconciliation=true (the ercot-172-specified C1 grain repair + C2 min() composition of the event-cap ceiling's own two measured layers; zero DOF; seam proof SP-1/2/3 exact pre-solve). THE 2024 OBJECT BEHAVES EXACTLY AS ATTRIBUTED: the 2024-04-28 shed CLEARS (predicted: +1,118.8 MW restored >= 565.1 shed) and 2024-05-08 shrinks (predicted: +353.3 < 550.3), shed 2->1 (G-SHED PASS), spike-day day-mean |err| 382->120 and 268->227 \\$/h, C3a-2024 +11.8%->+3.9%, NRMSE-2024 3.00->2.26, spurious falls EVERY year (10->9, 13->10, 1->0; G-SPUR PASS), and the ercot-167 RG-1 (G4-2024) kill CLEARS on its pre-registered definition. BUT the blanket min() over-restores fleet-wide: coal dispatch above the incumbent PRODUCT ceiling rises +0.98/+1.95/+2.73 TWh (bar +0.5; G-COAL148 FAIL - the ERCOT-148/149 adjudication is not survived), class annual energy moves far past the 0.5% G-SPAN band (2025 COAL_PRB +5.1%, CT_PEAKER -10.4%, ST_GAS -4.5%; 2023 CT_PEAKER -3.4%; G-SPAN FAIL), and the tail formation degrades (2024 model>\\$200 26->14 vs actual 53; 2025 3->0 vs 31; G-C3c FAIL). C3a-2023 (the owner object): -22.5% -> -23.8% (-1.3pp, inside the pre-registered P-C3a-2023 band '0 to -1.5pp more negative'). STRUCTURAL READING (rule 1): min() is correct ONLY where the two layers measure the SAME units' downtime (the ercot-172 named plants); the fleet-wide response measures the layers as substantially DISJOINT at most overlaps, where the product is the better composition - the correction must be UNIT-ATTRIBUTED inside the partial extract, not composition-wide (named successor). Keeper UNCHANGED at run168b. Full record: results/calibration/FINDING-ercot173-event-cap-reconciliation-2026-08-06.md.", "file": "frontend/data/backcast/runs/2026-08-06-run173b-event-cap-reconc.js", "id": "2026-08-06-run173b-event-cap-reconc", "iso": "ERCOT", "label": "run173b event cap reconc", "shorthand": "run173b-event-cap-reconc", "years": [2023, 2024, 2025]}, {"date": "2026-08-07", "definition": "caiso-180 Arm A0 CONTROL: the caiso-175 keeper recipe replayed at THIS head on the CURRENT (GUARD) outage envelope sha256 c4ded33d. Mandatory same-head control for the outage re-audit.", "file": "frontend/data/backcast/runs/2026-08-07-caiso-180-a0-control.js", "id": "2026-08-07-caiso-180-a0-control", "iso": "CAISO", "label": "caiso 180 a0 control", "shorthand": "caiso-180-a0-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-07", "definition": "caiso-180 Arm A1 PRE: the caiso-175 keeper recipe replayed at THIS head on the RECONSTRUCTED PRE-REGENERATION outage envelope (blob e40847c8 at 49e85fb4^, sha256 7f80b94e, 2023/2024/2025 = 439/405/509 windows). Counterfactual arm of the outage re-audit.", "file": "frontend/data/backcast/runs/2026-08-07-caiso-180-a1-pre.js", "id": "2026-08-07-caiso-180-a1-pre", "iso": "CAISO", "label": "caiso 180 a1 pre", "shorthand": "caiso-180-a1-pre", "years": [2023, 2024, 2025]}, {"date": "2026-08-07", "definition": "caiso-180 Arm A2 REGEN: the caiso-175 keeper recipe replayed at THIS head on the 2026-07-24 REGENERATED, GUARD-OFF outage envelope (blob 3dc01fae at 49e85fb4, sha256 a3599090, 2023/2024/2025 = 640/622/733 windows). Isolates the regeneration leg from the merit-order-guard leg.", "file": "frontend/data/backcast/runs/2026-08-07-caiso-180-a2-regen.js", "id": "2026-08-07-caiso-180-a2-regen", "iso": "CAISO", "label": "caiso 180 a2 regen", "shorthand": "caiso-180-a2-regen", "years": [2023, 2024, 2025]}, {"date": "2026-08-07", "definition": "gas_st taxonomy paired ARM (D-25 reclass) (per-year chain, year 2023)", "file": "frontend/data/backcast/runs/2026-08-07-miso-133-taxgs-arm.js", "id": "2026-08-07-miso-133-taxgs-arm", "iso": "MISO", "label": "miso 133 taxgs arm", "shorthand": "miso-133-taxgs-arm", "years": [2023, 2024, 2025]}, {"date": "2026-08-07", "definition": "gas_st taxonomy paired CONTROL (origin/main c710d17e code) (per-year chain, year 2023)", "file": "frontend/data/backcast/runs/2026-08-07-miso-133-taxgs-control.js", "id": "2026-08-07-miso-133-taxgs-control", "iso": "MISO", "label": "miso 133 taxgs control", "shorthand": "miso-133-taxgs-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-07", "definition": "THE DESIGNATED NYISO KEEPER from 2026-08-07 (promoted nyiso-131, owner decision D-27). Same-head replay_keeper of the incumbent keeper (2026-08-06-nyiso-128-solar-basis) re-solved on the D-25 gas_st fuel-taxonomy reclass, not a new recipe: natural-gas steam turbines now map to the dedicated gas_st fuel instead of folding into gas_ct, a rule 14 [R-ACCURATE] fix to the loader's fuel label (heat-rate fallback, VOM, EFORd, CO2/NOx, scoring-target fuel) with the class structure otherwise unchanged. VERIFIED, not asserted: of 698 scenario_config fields, the 693 shared with the incumbent are IDENTICAL and the 5 arm-only fields are post-keeper additions all at default False (including nyiso_li_tsl_n11_security, the nyiso-130 lever rejected on its own kill gate, confirmed NOT armed), so the full nyiso-128 lineage stays armed unchanged. NYISO's sole solve-affecting residue is the RED-Rochester ST_CHP synthesized-bin heat rate, 11.454 -> 10.3 MMBtu/MWh on 119.6 MW: demand-weighted LMP moves <=0.023 $/MWh in every year and the largest class-energy share by 0.052 TWh (ST_CHP, 2024); 34 of 188 numeric verdict fields move and no gate is approached, let alone crossed. DETERMINATION: CALIBRATED-WITH-CAVEATS, re-verified without a solve per rule 22 D-5(b) with all 8 criterion statuses identical to the incumbent (C1/C2/C3a/C3b/C4/C6/C8 PASS), C3c price tail/scarcity the sole ledgered caveat at budget 1 of 1 (2023 model 22h vs RT actual 10h, over-produced; 2024 model 3h vs 12h, under-produced). Evidence: docs/handoffs/taxonomy-gas-st-2026-08-07.md \u00a74.1, docs/handoffs/nyiso-taxgs-promotion-2026-08-07.md.", "file": "frontend/data/backcast/runs/2026-08-07-nyiso-131-taxgs-arm.js", "id": "2026-08-07-nyiso-131-taxgs-arm", "iso": "NYISO", "label": "nyiso 131 taxgs arm", "shorthand": "nyiso-131-taxgs-arm", "years": [2023, 2024, 2025]}, {"date": "2026-08-07", "definition": "gas_st taxonomy paired CONTROL (origin/main c710d17e code)", "file": "frontend/data/backcast/runs/2026-08-07-nyiso-131-taxgs-control.js", "id": "2026-08-07-nyiso-131-taxgs-control", "iso": "NYISO", "label": "nyiso 131 taxgs control", "shorthand": "nyiso-131-taxgs-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-07", "definition": "ercot-176 CONTROL / KEEPER RE-SOLVE. The run168b keeper recipe replayed at HEAD (scripts/replay_keeper.py, ZERO deltas), full span 2023-2025. Registered under the owner ruling of 2026-08-07 (ercot-175 decision card): the control replay doubles as the keeper re-solve, RETIRING the run168b non-reproduction item (ercot-175 \u00a75 item 4 / ercot-173 \u00a75). IT REPRODUCES: C3a-2023 -32.2% -> -32.4% (0.2pp), C3b-2023 0.604 -> 0.602, C3b-2024 0.206 -> 0.205, and the three ledgered C3c tail counts are IDENTICAL (61/181, 25/53, 3/31). Determination NOT-YET, fail set {C3a, C3b} - unchanged from run168b; C1/C2/C4/C6/C8 PASS, C3c ledgered CAVEAT x3. *** The session's own mechanism is NOT armed here. ercot_offline_commit_offer (the owner-authorized ERCOT-151 \u00a73 offline-increment SLOW-START tier) was BUILT default-off and measured PROVABLY INERT before any solve, so its arm was never solved and no arm run is registered (stated explicitly, rules 15/16). Measured pool_frac_CC is 0.0002-0.0007 of CC live capability - ~30x below the pre-registered 0.02 inertness threshold - putting the offer boundary at 0.9993-0.9994 against a largest within-plant tranche midpoint of 0.9984, so no row clears it in any hour of any year; its ladder is cheap too (p70 24-40x gas ~ $100/MWh vs the CT tier's p50 $271-707). ERCOT's merchant CC fleet does not sit offline-and-cheap at tight hours - a third independent corroboration of ERCOT-163 (DAM instrument) and ercot-175 (SCED sub-$200 slice), now on the CC class's own full-year RT conduct. The charter's 18.1 GW / 13.5 GW premise stays REFUTED and was not relied on. *** SIDE FINDING (owner item): fleet assembly records unit physics on the committed tranche only, so every econ*/peak* bid row reads min_down=min_run=0 and a rule-18 physics gate is vacuous at that grain - which means the ARMED keeper mechanism ercot_faststart_pool_offer admits every CT bid row regardless of physics. Reported, NOT acted on (it would move the keeper). Records: docs/PRECOMMIT-ercot176-offline-increment-2026-08-07.md (+3 pre-solve amendments), results/calibration/FINDING-ercot176-offline-increment-slowstart-2026-08-07.md, results/calibration/ercot176_offline_commit_seamproof.json.", "file": "frontend/data/backcast/runs/2026-08-07-run176-control-offline-increment.js", "id": "2026-08-07-run176-control-offline-increment", "iso": "ERCOT", "label": "run176 control offline increment", "market_story": "Unchanged from the run168b recipe this run replays - no mechanism was added, removed or re-tuned. ERCOT's price formation here is: coal two-shifts through price formation on its own measured per-plant year curves (backing to the mustrun floor on ordinary overnight LMPs, exactly as SCED did); merchant gas CC self-commits and is held at its measured LSL/HSL p50 by the commitment bridge rather than by a floor tuned to the residual; the offline fast-start CT pool is offered at its own measured start-inclusive SCED2 ladder; and the multiproduct AS co-optimisation holds ERCOT's measured hourly plan, with the date-gated ECRS conservative-deployment family forming the scarcity hours it can reach. What this run newly establishes about the market is a NEGATIVE with a market story: the slow-start half of the offline increment carries no MW. ERCOT's CC fleet does not wait offline-and-cheap for tight hours - it self-commits into real time and is already loaded (96.4% committed / 98.0% loaded at the 2023 gap hours), so its RT offline-startable share measures 0.02-0.07% of live capability and what little exists offers near cost, not at scarcity. The missed 2023 tail is therefore not a mispriced CC start; it remains the ledgered C3c model-class limitation - equilibrium conduct on the energy stack that a competitive-offer LP does not form.", "shorthand": "run176-control-offline-increment", "years": [2023, 2024, 2025]}, {"date": "2026-08-08", "definition": "caiso-183 ARM B0 CONTROL: the caiso-175 keeper recipe replayed at THIS head on the COMMITTED day-grain outage envelope (sha c4ded33d). No model change is active on this arm; it exists to measure same-head drift, which caiso-180 and caiso-181 both measured at exactly $0.000.", "file": "frontend/data/backcast/runs/2026-08-08-caiso-183-b0-control.js", "id": "2026-08-08-caiso-183-b0-control", "iso": "CAISO", "label": "caiso 183 b0 control", "shorthand": "caiso-183-b0-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-08", "definition": "caiso-183 ARM B1 TREATED: the caiso-175 keeper recipe replayed at THIS head on the REPAIRED hour-grain CAISO outage envelope. Single delta vs B0 = data/raw/campd-unit-outages-CAISO.csv re-derived with --hour-grain, which carries the DETECTED start/end hour through the schema so the loader stops re-expanding every window to 00:00-23:00. ZERO DOF, zero new fitted scalars, detection byte-identical (BE-3: same 4328 rows, same tuples, same order); only the expressed grain differs.", "file": "frontend/data/backcast/runs/2026-08-08-caiso-183-b1-hour.js", "id": "2026-08-08-caiso-183-b1-hour", "iso": "CAISO", "label": "caiso 183 b1 hour", "shorthand": "caiso-183-b1-hour", "years": [2023, 2024, 2025]}, {"date": "2026-08-08", "definition": "THE DESIGNATED NYISO KEEPER from 2026-08-08 (promoted nyiso-132, owner ruling in session). Arms one field over the outgoing keeper recipe 2026-08-07-nyiso-131-taxgs-arm: RENEWABLE_AVG_CF['NYISO']['solar'] 0.15 -> 0.1955, an UNGATED rule 14 [R-ACCURATE] constants.py re-level with ZERO free parameters (DOF ledger 35 -> 36 entries, n_residual UNCHANGED at 6), replacing a self-declared Tier-3 approximation flagged 'needs-citation' with the registered fleet's MEASURED mature-year CF (2026 Gold Book Table III-2a: 981.8 GWh over 573.4 MW for 2025; 573.4 x 8760 x 0.1955 reproduces it to 0.02 %). DETERMINATION: CALIBRATED-WITH-CAVEATS, re-verified 2026-08-08 without a solve per rule 22 D-5(b), IDENTICAL to the superseded keeper -- all 8 criterion statuses match (C1/C2/C3a/C3b/C4/C6/C8 PASS; C3a +8.8/+0.7/-3.4 % 2023-2025), C3c the sole ledgered caveat at budget 1 of 1 (2023 model 21h vs RT actual 10h, over-produced; 2024 model 3h vs 12h, under-produced; 2025 passes the band at 24h vs 42h) -- NO GATED CRITERION REGRESSES. REPORTED AGAINST INTEREST, NOT a clean win: solar vs the published Gold Book registry goes -7.1/+2.4/-23.3 % -> +20.9/+33.2/-0.1 %, trading one report-only advisory-band breach (calibration_verdict.VRE_TOL, +/-10 %) for two -- the arm buys an essentially exact 2025 but pushes 2023 and 2024 outside the band the control had held. The D-10 free-class rescore marks solar 'PINNED (advisory-only, excluded from skill claims)' in all three years, so no gated criterion moves on it; the named cause is a separate open item under rule 19 [R-ONE-MECH] -- the model has no commissioning curve, so one mature-fleet CF cannot track a fleet whose realized CF runs 0.1468-0.1955 across years. Evidence: results/calibration/FINDING-nyiso132-solar-cf-level-2026-08-07.md, PREREG-nyiso132-solar-cf-level-2026-08-07.md.", "file": "frontend/data/backcast/runs/2026-08-08-nyiso-132-cf-arm.js", "id": "2026-08-08-nyiso-132-cf-arm", "iso": "NYISO", "label": "nyiso 132 cf arm", "shorthand": "nyiso-132-cf-arm", "years": [2023, 2024, 2025]}, {"date": "2026-08-08", "definition": "nyiso-132 solar CF level: paired CONTROL (origin/main constants, RENEWABLE_AVG_CF NYISO solar 0.15), keeper recipe 2026-08-07-nyiso-131-taxgs-arm", "file": "frontend/data/backcast/runs/2026-08-08-nyiso-132-cf-control.js", "id": "2026-08-08-nyiso-132-cf-control", "iso": "NYISO", "label": "nyiso 132 cf control", "shorthand": "nyiso-132-cf-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-08", "definition": "nyiso-133 ARM: single delta nyiso_solar_registry_cod_dates=True on the keeper 2026-08-08-nyiso-132-cf-arm recipe. NYISO market-solar in-service date basis moves from the Gold Book registration date to EIA-860's Operating Month (PREREG-nyiso133-market-solar-cod-basis-2026-08-08.md).", "file": "frontend/data/backcast/runs/2026-08-08-nyiso-133-cod-arm.js", "id": "2026-08-08-nyiso-133-cod-arm", "iso": "NYISO", "label": "nyiso 133 cod arm", "shorthand": "nyiso-133-cod-arm", "years": [2023, 2024, 2025]}, {"date": "2026-08-08", "definition": "nyiso-133 PAIRED CONTROL: keeper 2026-08-08-nyiso-132-cf-arm recipe replayed at HEAD with ZERO delta. Baseline for the nyiso_solar_registry_cod_dates single-delta A/B (PREREG-nyiso133-market-solar-cod-basis-2026-08-08.md).", "file": "frontend/data/backcast/runs/2026-08-08-nyiso-133-cod-control.js", "id": "2026-08-08-nyiso-133-cod-control", "iso": "NYISO", "label": "nyiso 133 cod control", "shorthand": "nyiso-133-cod-control", "years": [2023, 2024, 2025]}, {"date": "2026-08-08", "definition": "(PROBE \u2014 REJECTED-AS-ARMED) ercot-178 ARM: control + ercot_offer_surface_continuous=true \u2014 the pre-registered CONTINUOUS net-load-percentile conditioning grain of the four armed measured offer surfaces (matrix \u00a75.1 item 21). HEADLINE C3a-2023 -32.4% -> -19.7% (+$8.18/MWh lw) BUT 67.5% OF THAT GAIN IS MANUFACTURED VOLL SHORTAGE: 10 NEW load-shed hours carry +$5.53 of the +$8.18, overshooting actual by >1.5x in 7 of 10 (2023-08-26 18:00 actual $570 -> arm $5,000; 2023-08-27 15:00 actual $359 -> arm $5,000) against reality's 4 hours >= $4,500 in all of 2023 \u2014 the ercot-48/49 right-number-wrong-mechanism signature the owner REJECTED WITH CAUSE 2026-07-09. Net offer-formation gain is +$2.62/MWh (32%). Other movements, C3b-2023 0.602 -> 0.349, 2025 C3a -9.1% -> ~-4%, C3c-2024 crosses INTO band (28/53). REJECTED on its own pre-registered kill gates: G-OWNER/G-SPAN' ~20x (2024 ST_GAS +9.7%/CT +8.7%/CC -3.0%; 2025 ST_GAS +12.7%/CT +11.4% vs 0.5% cap \u2014 the de-dilution is two-sided and the 2024/25 RT/pool node bases are sample-day-thin, so continuous interpolation bridges sample conduct across the whole rank axis); G-SHED (2023 shed 4 -> 14); G-C3c (2023 61 -> 57 away from 181; 2025 3 -> 0); C3b-2024 0.205 -> 0.208. Named successor: form (b) finer edges ABOVE p97 only. FINDING-ercot178-continuous-grain-2026-08-08.md.", "file": "frontend/data/backcast/runs/2026-08-08-run178-continuous-grain.js", "id": "2026-08-08-run178-continuous-grain", "iso": "ERCOT", "label": "run178 continuous grain", "shorthand": "run178-continuous-grain", "years": [2023, 2024, 2025]}, {"date": "2026-08-08", "definition": "ercot-178 CONTROL: the run176 keeper recipe replayed at HEAD fa72e921 with ZERO deltas (PRECOMMIT-ercot178 \u00a78). REPRODUCES THE KEEPER BYTE-IDENTICALLY \u2014 price series array-equal in all three years (lw 43.453/31.762/33.378) \u2014 the third consecutive keeper reproduction at a new HEAD. NOT-YET, fail set {C3a, C3b} identical to the keeper: C3a-2023 -32.4%, C3b 0.602/0.205, C3c ledgered 61/181, 25/53, 3/31.", "file": "frontend/data/backcast/runs/2026-08-08-run178-control.js", "id": "2026-08-08-run178-control", "iso": "ERCOT", "label": "run178 control", "shorthand": "run178-control", "years": [2023, 2024, 2025]}];